"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95083"],{63589(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_vagas_obrigatoria","status":422,"titulo":"Composi\xe7\xe3o de vagas da modalidade \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_vagas_obrigatoria","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada n\xe3o declarou `composicaoVagas`. A composi\xe7\xe3o de\\nvagas decide como a modalidade entra na aritm\xe9tica do quadro de vagas \u2014\\nampla concorr\xeancia residual, sub-reserva da Lei 12.711, retirada de outra\\nmodalidade (`RETIRA_DE`, ver\\n[`composicao_origem_obrigatoria`](/erros/uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria)),\\nou suplemento ao total publicado. Roda antes das confer\xeancias de coer\xeancia de\\n`RETIRA_DE` \u2014 sem uma composi\xe7\xe3o declarada, n\xe3o h\xe1 como avaliar se o c\xf3digo\\nde origem \xe9 coerente com ela.","**`composicaoVagas` n\xe3o vem do corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de\\nvagas** \u2014 \xe9 copiada do cadastro de modalidades de Configura\xe7\xe3o, no momento\\nem que a modalidade \xe9 selecionada (`IModalidadeReader`). O cadastro nunca\\ngrava uma modalidade sem esse campo \u2014 quando ele \xe9 omitido no cadastro, um\\nvalor padr\xe3o (`RESIDUAL_DO_VO`) \xe9 aplicado; n\xe3o existe modalidade cadastrada\\ncom composi\xe7\xe3o de vagas literalmente vazia. O que dispara este c\xf3digo, na\\npr\xe1tica, \xe9 o token de composi\xe7\xe3o do cadastro **n\xe3o ser reconhecido** pelo\\nvocabul\xe1rio do m\xf3dulo Sele\xe7\xe3o \u2014 hoje os dois vocabul\xe1rios coincidem, ent\xe3o\\no cen\xe1rio real \xe9 uma diverg\xeancia futura entre eles (o cadastro evoluindo\\nantes deste m\xf3dulo), n\xe3o um dado corrompido.","N\xe3o acumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira que falhar que\\ninterrompe a cria\xe7\xe3o da modalidade.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma confer\xeancia roda de novo, sozinha."],"comoResolver":["O campo n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade cadastrada\\nem Configura\xe7\xe3o. Confira l\xe1 a composi\xe7\xe3o de vagas cadastrada; se ela\\nparecer correta e o erro persistir, \xe9 sinal de que o token que o cadastro\\nemite n\xe3o \xe9 mais reconhecido pelo m\xf3dulo Sele\xe7\xe3o \u2014 um problema de\\nsincroniza\xe7\xe3o entre os dois vocabul\xe1rios, n\xe3o de dado ausente.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema n\xe3o est\xe1 no que\\nfoi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada. Isso indica uma\\ninconsist\xeancia nessa vers\xe3o; abra uma investiga\xe7\xe3o em vez de tentar\\ncorrigir pelo envio."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);